// План: specs/cards.md, тест 2.1. Тикет #d9877d (עבר QA 17.11.2026). Цифры временные, выдаются сервером — сверяем совпадение, не значения.
// Только просмотр → @prod-safe.
import { test, expect } from '../../fixtures';
import { SHARED_WALLET_ID, SHARED_WALLET_NAME, MASK, openAllCards, waitMasks, digitsOfCard, expectNoFullCardNumber } from './helpers';

test.describe('4 ספרות אחרונות — עקביות', () => {
  test('אותן 4 ספרות ב«כל הכרטיסים» וב«ביצוע תשלום» של אותו ארנק, ללא שינוי אחרי רענון, בלי מספר מלא @prod-safe #d9877d', async ({ asUser }) => {
    const manager = await asUser('client');

    // 1. «ביצוע תשלום» общего кошелька.
    await manager.goto(`/wallet/shared/${SHARED_WALLET_ID}`);
    await manager.getByRole('button', { name: 'לשימוש בכרטיס' }).click();
    await expect(manager.getByText('ביצוע תשלום').first()).toBeVisible({ timeout: 30_000 });
    const payDigits = (await waitMasks(manager, 1))[0];
    expect(`•••• •••• •••• ${payDigits}`).toMatch(MASK);
    await expectNoFullCardNumber(manager);

    // 2. Те же цифры в «כל הכרטיסים» на карточке этого кошелька.
    await openAllCards(manager);
    await waitMasks(manager, 2);
    expect(await digitsOfCard(manager, SHARED_WALLET_NAME)).toBe(payDigits);
    await expectNoFullCardNumber(manager);

    // 3. После перезагрузки страницы цифры не меняются.
    await manager.reload();
    await expect.poll(async () => (await waitMasks(manager, 2)).length).toBeGreaterThanOrEqual(2);
    expect(await digitsOfCard(manager, SHARED_WALLET_NAME)).toBe(payDigits);

    await manager.goto(`/wallet/shared/${SHARED_WALLET_ID}/pay`);
    await expect(manager.getByText('ביצוע תשלום').first()).toBeVisible({ timeout: 30_000 });
    expect((await waitMasks(manager, 1))[0]).toBe(payDigits);
    await expectNoFullCardNumber(manager);
  });
});
